const input = $json || {};
const config = input.configSnapshot || input.config_snapshot || {};
const jira = config.jira || {};
const models = config.models || {};
const cleanBase = (value, fallback) => {
  const s = String(value || fallback || '');
  return s.endsWith('/') ? s.slice(0, -1) : s;
};
return [{
  json: {
    jobId: input.jobId || input.job_id || ('STC-' + Date.now()),
    projectId: input.projectId || input.project_id || null,
    projectName: input.projectName || input.project_name || 'Unknown Project',
    requestedBy: input.requestedBy || input.requested_by || null,
    settingsVersion: input.settingsVersion || input.settings_version || null,
    startedAt: input.startedAt || input.createdAt || new Date().toISOString(),
    jiraBaseUrl: cleanBase(input.jiraBaseUrl || jira.baseUrl, 'https://anujalhans1.atlassian.net'),
    jiraProjectKey: input.jiraProjectKey || jira.projectKey || 'KAN',
    testCaseIssueTypeName: input.testCaseIssueTypeName || jira.testCaseIssueTypeName || jira.testCaseIssueType || 'Test Case',
    generationModel: input.generationModel || models.generationModel || 'gpt-4.1-mini',
    maxTokens: Math.max(6000, Number(input.maxTokens || models.maxTokens || 12000) || 12000),
    idempotencyLabelPrefix: input.idempotencyLabelPrefix || jira.idempotencyLabelPrefix || 'qops',
    productOwner: input.productOwner || input.product_owner || 'Product Owner',
    configSnapshot: config
  }
}];

const request = $('Normalize Story Test Case Request').first().json;
const rows = $input.all().map(item => item.json || {});
const normalizedProjectName = String(request.projectName || '').trim().toLowerCase();
const matchingJob = rows.find((row) => {
  const rowProjectId = String(row.project_id || '').trim();
  const rowProjectName = String(row.input?.projectName || row.input?.project_name || '').trim().toLowerCase();
  if (request.projectId && rowProjectId) return rowProjectId === String(request.projectId);
  return rowProjectName === normalizedProjectName;
});
if (!matchingJob) throw new Error('No completed Epics & User Stories generation job was found for project=' + request.projectName + '. Generate Epics & User Stories first, then retry Story Test Cases.');
const storySourceJobId = matchingJob.job_id || null;
const stories = matchingJob.output?.jira?.stories || matchingJob.output?.stories || [];
if (!Array.isArray(stories) || !stories.length) throw new Error('The latest Epics & User Stories job for project=' + request.projectName + ' does not contain Jira story references. Story Test Cases cannot be created until user stories exist in Jira.');
return stories.map((story, index) => ({ json: { ...request, storySourceJobId, storyIndex: index + 1, totalStories: stories.length, storyKey: story.storyKey || story.key || '', storyId: story.storyId || story.id || '', storySummary: story.summary || '', storyCorrelationId: story.storyCorrelationId || story.userStoryId || '', storyStableLabel: story.stableLabel || '', storySelf: story.storySelf || story.self || '', storyLink: story.storyKey ? request.jiraBaseUrl + '/browse/' + story.storyKey : null } }));

const source = $('Build Story Source Items').item.json;
const issue = $json || {};
const NL = String.fromCharCode(10);
function flattenAdf(node) {
  if (!node) return '';
  if (Array.isArray(node)) return node.map(flattenAdf).filter(Boolean).join(NL);
  if (typeof node === 'string') return node;
  if (node.type === 'text') return node.text || '';
  const content = Array.isArray(node.content) ? node.content.map(flattenAdf).filter(Boolean).join(node.type === 'paragraph' ? '' : NL) : '';
  if (node.type === 'paragraph') return content.trim();
  if (node.type === 'bulletList' || node.type === 'orderedList') return content.trim();
  if (node.type === 'listItem') return '- ' + content.trim();
  if (node.type === 'heading') return content.trim();
  return content.trim();
}
const descriptionText = flattenAdf(issue.fields?.description || '').replace(new RegExp(NL + '{3,}', 'g'), NL + NL).trim();
const storySummary = issue.fields?.summary || source.storySummary || source.storyKey;
const system = [
  'You are a Senior QA Test Architect with 15+ years of experience designing enterprise-scale, risk-driven, automation-ready Jira Test Case issues from existing Jira user stories.',
  'You specialize in requirement decomposition, boundary and edge case design, negative testing, failure modeling, UI/API/integration validation, and automation feasibility optimization.',
  'Return one JSON object only. No markdown. No prose outside JSON.',
  'Avoid generic test cases. Every case must be specific to the story, realistic, execution-ready, and traceable to the available Jira story details.',
  'Use this exact schema:',
  '{',
  '  "storyKey": "KAN-123",',
  '  "storySummary": "Story title",',
  '  "testCases": [',
  '    {',
  '      "testCaseId": "TC-001",',
  '      "summary": "Short Jira-ready test case title",',
  '      "objective": "Why this test exists",',
  '      "requirementReference": "Story KAN-123 acceptance criterion or story detail covered",',
  '      "testLevel": "UI | API | SIT | FAT | Regression | Security | Performance | Network | Data | Accessibility",',
  '      "testCategory": "Positive | Negative | Boundary | Edge | Alternate | Exception | Integration | Validation | Resilience",',
  '      "preconditions": ["..."],',
  '      "testSteps": ["..."],',
  '      "testData": ["..."],',
  '      "expectedResult": "Observable outcome",',
  '      "priority": "High",',
  '      "riskLevel": "High",',
  '      "testType": "functional",',
  '      "automationFeasibility": "High",',
  '      "acceptanceCriteriaCovered": ["..."],',
  '      "notes": ["..."]',
  '    }',
  '  ]',
  '}',
  'Generate maximum useful coverage for this story. Do not cap output at 7 test cases.',
  'For simple or low-risk stories, generate at least 8 to 12 distinct test cases.',
  'For medium-complexity stories, generate at least 15 to 25 distinct test cases.',
  'For complex, integration-heavy, data-heavy, payment, authentication, authorization, or high-risk stories, generate 25 to 40 distinct test cases when the story details support it.',
  'Cover UI, FAT, SIT, regression, API/service, data validation, positive, negative, boundary, edge, alternate, exception, integration, security, performance, network/resilience, and accessibility scenarios wherever applicable.',
  'Do not invent unsupported systems or requirements. If a coverage type is not applicable, omit it rather than creating filler.',
  'Prioritize breadth first, then depth: cover distinct behaviors, validations, integrations, roles, permissions, data states, and failure modes before adding variants.',
  'Keep titles concise and professional for Jira.',
  'Every test case must have at least 3 clear steps, concrete test data where applicable, a concrete expected result, priority, risk level, and automation feasibility.',
  'Use stable, sequential testCaseId values from TC-001 onward.'
].join(NL);
const user = ['Project: ' + source.projectName, 'Story Key: ' + source.storyKey, 'Story Summary: ' + storySummary, 'Story Correlation ID: ' + (source.storyCorrelationId || 'N/A'), '', 'Story Description:', descriptionText || 'No Jira description was available. Use the story summary and source context only.', '', 'Generate exhaustive, enterprise-grade, execution-ready Jira Test Case issues for this story.'].join(NL);
return [{ json: { ...source, storySummary, storyDescriptionText: descriptionText, system, user } }];

const source = $('Prepare Story Test Case Prompt').item.json;
const raw = $json.output ?? $json.text ?? $json.response ?? $json;
const NL = String.fromCharCode(10);
const BACKSLASH = String.fromCharCode(92);
const stringifyRaw = value => {
  if (value && typeof value === 'object') {
    if (typeof value.output === 'string') return value.output;
    if (typeof value.text === 'string') return value.text;
    if (typeof value.response === 'string') return value.response;
  }
  return String(value || '').trim();
};
const count = (text, pattern) => (text.match(pattern) || []).length;
const truncationMessage = text => 'Story Test Case parser detected incomplete or truncated model JSON for story ' + source.storyKey + '. Output chars=' + text.length + ', maxTokens=' + source.maxTokens + '. Please rerun or reduce prompt size.';
const extractBalancedJsonObject = text => {
  const firstBrace = text.indexOf('{');
  if (firstBrace < 0) throw new Error('Story Test Case parser received a response without a JSON object. Raw preview: ' + text.slice(0, 500));
  let depth = 0;
  let inString = false;
  let escaped = false;
  for (let i = firstBrace; i < text.length; i++) {
    const char = text[i];
    if (inString) {
      if (escaped) escaped = false;
      else if (char === BACKSLASH) escaped = true;
      else if (char === '"') inString = false;
      continue;
    }
    if (char === '"') inString = true;
    else if (char === '{') depth += 1;
    else if (char === '}') { depth -= 1; if (depth === 0) return text.slice(firstBrace, i + 1); }
  }
  throw new Error(truncationMessage(text) + ' JSON balance: {' + count(text, /{/g) + '/' + count(text, /}/g) + '}');
};
let text = stringifyRaw(raw);
if (!text) throw new Error('Story Test Case parser received an empty model response.');
const fence = String.fromCharCode(96, 96, 96);
const fenceStart = text.indexOf(fence);
const fenceEnd = text.lastIndexOf(fence);
if (fenceStart >= 0 && fenceEnd > fenceStart) {
  const firstLineEnd = text.indexOf(NL, fenceStart + fence.length);
  if (firstLineEnd >= 0 && fenceEnd > firstLineEnd) text = text.slice(firstLineEnd + 1, fenceEnd).trim();
}
const candidate = extractBalancedJsonObject(text);
let parsed;
try { parsed = JSON.parse(candidate); } catch (error) { throw new Error('Story Test Case parser failed to parse model JSON: ' + error.message + '. Raw preview: ' + candidate.slice(0, 800)); }
if (!Array.isArray(parsed.testCases) || !parsed.testCases.length) throw new Error('Story Test Case generator returned no testCases for story ' + source.storyKey + '.');
return [{ json: { ...source, parsed, storyWordCount: Math.max(1, candidate.trim().split(new RegExp(BACKSLASH + 's+')).length), storyTokensInput: Math.max(1, Math.ceil(((source.system || '') + (source.user || '')).length / 4)), storyTokensOutput: Math.max(1, Math.ceil(candidate.length / 4)), storyEstimatedCostUsd: Number((((Math.max(1, Math.ceil(((source.system || '') + (source.user || '')).length / 4)) * 0.40) + (Math.max(1, Math.ceil(candidate.length / 4)) * 1.60)) / 1000000).toFixed(6)) } }];

const source = $json;
const parsed = source.parsed || {};
const normalizeArray = value => Array.isArray(value) ? value.map(v => String(v || '').trim()).filter(Boolean) : (String(value || '').trim() ? [String(value).trim()] : []);
const slugify = value => String(value || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 50);
function adfParagraph(text, strongLabel) { const content = []; if (strongLabel) content.push({ type: 'text', text: strongLabel + ': ', marks: [{ type: 'strong' }] }); if (text) content.push({ type: 'text', text: String(text).slice(0, 12000) }); return { type: 'paragraph', content }; }
function adfHeading(text, level = 3) { return { type: 'heading', attrs: { level }, content: [{ type: 'text', text: String(text).slice(0, 250) }] }; }
function adfBulletList(items) { const normalized = normalizeArray(items); if (!normalized.length) return null; return { type: 'bulletList', content: normalized.map(item => ({ type: 'listItem', content: [{ type: 'paragraph', content: [{ type: 'text', text: item.slice(0, 800) }] }] })) }; }
const storySummary = parsed.storySummary || source.storySummary || source.storyKey;
const testCases = Array.isArray(parsed.testCases) ? parsed.testCases : [];
return testCases.map((testCase, index) => {
  const testCaseId = String(testCase.testCaseId || ('TC-' + String(index + 1).padStart(3, '0'))).trim();
  const summary = String(testCase.summary || ('Test ' + testCaseId + ' for ' + storySummary)).trim();
  const stableLabel = [source.idempotencyLabelPrefix || 'qops', 'tc', slugify(source.storyCorrelationId || source.storyKey), slugify(testCaseId), slugify(summary)].filter(Boolean).join('-').slice(0, 120);
  const preconditions = normalizeArray(testCase.preconditions);
  const testSteps = normalizeArray(testCase.testSteps);
  const testData = normalizeArray(testCase.testData);
  const acceptanceCriteriaCovered = normalizeArray(testCase.acceptanceCriteriaCovered);
  const notes = normalizeArray(testCase.notes);
  const requirementReference = String(testCase.requirementReference || (source.storyKey + ' story details')).trim();
  const testLevel = String(testCase.testLevel || 'UI').trim();
  const testCategory = String(testCase.testCategory || 'Functional').trim();
  const riskLevel = String(testCase.riskLevel || 'Medium').trim();
  const automationFeasibility = String(testCase.automationFeasibility || 'Medium').trim();
  const jiraDescription = { type: 'doc', version: 1, content: [adfHeading('Source Story', 3), adfParagraph(source.storyKey + ' - ' + storySummary), adfParagraph(testCase.objective || '', 'Objective'), adfParagraph(requirementReference, 'Requirement Reference'), adfParagraph(testLevel, 'Test Level'), adfParagraph(testCategory, 'Test Category'), adfParagraph(riskLevel, 'Risk Level'), adfParagraph(automationFeasibility, 'Automation Feasibility'), preconditions.length ? adfHeading('Preconditions', 3) : null, preconditions.length ? adfBulletList(preconditions) : null, testSteps.length ? adfHeading('Test Steps', 3) : null, testSteps.length ? adfBulletList(testSteps.map((step, stepIndex) => (stepIndex + 1) + '. ' + step)) : null, testData.length ? adfHeading('Test Data', 3) : null, testData.length ? adfBulletList(testData) : null, adfHeading('Expected Result', 3), adfParagraph(testCase.expectedResult || 'Expected result not provided by generator.'), acceptanceCriteriaCovered.length ? adfHeading('Acceptance Criteria Covered', 3) : null, acceptanceCriteriaCovered.length ? adfBulletList(acceptanceCriteriaCovered) : null, notes.length ? adfHeading('Notes', 3) : null, notes.length ? adfBulletList(notes) : null, adfHeading('Traceability', 3), adfParagraph(source.storyKey + ' | ' + (source.storyCorrelationId || 'N/A') + ' | Source Job ' + (source.storySourceJobId || 'N/A'))].filter(Boolean) };
  return { json: { ...source, testCaseIndex: index + 1, testCaseId, testCaseSummary: summary, priority: String(testCase.priority || 'Medium'), testType: String(testCase.testType || 'functional'), requirementReference, testLevel, testCategory, riskLevel, automationFeasibility, objective: String(testCase.objective || '').trim(), preconditions, testSteps, testData, expectedResult: String(testCase.expectedResult || '').trim(), acceptanceCriteriaCovered, notes, stableLabel, jiraDescription, createIssueBody: { fields: { project: { key: source.jiraProjectKey }, issuetype: { name: source.testCaseIssueTypeName || 'Test Case' }, summary, description: jiraDescription, labels: [stableLabel, 'qops-story-test-cases', ('story-' + slugify(source.storyKey)).slice(0, 80)] } }, linkIssueBody: { type: { name: 'Relates' }, inwardIssue: { key: source.storyKey }, outwardIssue: { key: '__REPLACE_TEST_CASE_KEY__' }, comment: { body: { type: 'doc', version: 1, content: [{ type: 'paragraph', content: [{ type: 'text', text: 'Linked by Q-Ops Story Test Cases generation.' }] }] } } } } };
});

const expandedItems = $('Expand Story Test Case Items').all().map((item) => item.json || {});
const createdItems = $('Create Jira Test Case').all();

function pairedIndex(item, fallback) {
  const paired = Array.isArray(item.pairedItem) ? item.pairedItem[0] : item.pairedItem;
  return Number.isInteger(paired?.item) ? paired.item : fallback;
}

return createdItems.map((item, index) => {
  const created = item.json || {};
  const source = expandedItems[pairedIndex(item, index)] || expandedItems[index] || expandedItems[0] || {};
  return {
    json: {
      ...source,
      action: 'created',
      testcaseKey: created.key,
      testcaseId: created.id,
      testcaseSelf: created.self,
      testcaseLink: source.jiraBaseUrl + '/browse/' + created.key
    }
  };
});

function safeAll(nodeName) { try { return $(nodeName).all().map((item) => item.json || {}); } catch (error) { if (String(error?.message || error).includes("hasn't been executed")) return []; throw error; } }
const createdItems = safeAll('Normalize Created Story Test Case');
const reusedItems = safeAll('Normalize Existing Story Test Case');
const allItems = [...createdItems, ...reusedItems];
if (!allItems.length) throw new Error('Story Test Case generator did not produce any reusable or created Jira Test Cases.');
const perStoryMetrics = $('Robust Story Test Case Parser').all().map(item => item.json || {});
const storyMap = new Map();
allItems.forEach((item) => { if (!storyMap.has(item.storyKey)) storyMap.set(item.storyKey, { storyKey: item.storyKey, storyId: item.storyId, summary: item.storySummary, storyCorrelationId: item.storyCorrelationId, storyLink: item.storyLink }); });
const stories = Array.from(storyMap.values());
const testCases = allItems.map((item) => ({ action: item.action, testcaseKey: item.testcaseKey, testcaseId: item.testcaseId, testcaseSummary: item.testCaseSummary, testcaseLink: item.testcaseLink, storyKey: item.storyKey, storySummary: item.storySummary, stableLabel: item.stableLabel, priority: item.priority, riskLevel: item.riskLevel, testType: item.testType, testLevel: item.testLevel, testCategory: item.testCategory, automationFeasibility: item.automationFeasibility, requirementReference: item.requirementReference }));
const mappings = allItems.map((item) => ({ storyKey: item.storyKey, storySummary: item.storySummary, testcaseKey: item.testcaseKey, testcaseSummary: item.testCaseSummary, action: item.action }));
const wordCount = perStoryMetrics.reduce((sum, item) => sum + Number(item.storyWordCount || 0), 0);
const tokensInput = perStoryMetrics.reduce((sum, item) => sum + Number(item.storyTokensInput || 0), 0);
const tokensOutput = perStoryMetrics.reduce((sum, item) => sum + Number(item.storyTokensOutput || 0), 0);
const estimatedCostUsd = Number(perStoryMetrics.reduce((sum, item) => sum + Number(item.storyEstimatedCostUsd || 0), 0).toFixed(6));
const first = allItems[0];
return [{ json: { documentType: 'story_test_cases', jobId: first.jobId, projectId: first.projectId, projectName: first.projectName, sourceUserStoryJobId: first.storySourceJobId || null, stories, testCases, mappings, jira: { projectKey: first.jiraProjectKey, created: testCases.filter(item => item.action === 'created').length, reused: testCases.filter(item => item.action === 'reused').length }, wordCount, tokensInput, tokensOutput, tokensTotal: tokensInput + tokensOutput, estimatedCostUsd } }];

const expandedItems = $('Expand Story Test Case Items').all().map((item) => item.json || {});
const searchItems = $input.all();

function pairedIndex(item, fallback) {
  const paired = Array.isArray(item.pairedItem) ? item.pairedItem[0] : item.pairedItem;
  return Number.isInteger(paired?.item) ? paired.item : fallback;
}

return searchItems.map((item, index) => {
  const search = item.json || {};
  const source = expandedItems[pairedIndex(item, index)] || expandedItems[index] || expandedItems[0] || {};
  const existing = Array.isArray(search.issues) ? search.issues[0] : null;
  if (!existing?.key) throw new Error('Expected an existing Jira Test Case issue for stable label ' + source.stableLabel + ' but none was returned.');
  return {
    json: {
      ...source,
      action: 'reused',
      testcaseKey: existing.key,
      testcaseId: existing.id || null,
      testcaseSelf: existing.self || null,
      testcaseLink: source.jiraBaseUrl + '/browse/' + existing.key
    }
  };
});
